ST.xhtml:p:
NCAxisAbs(
     AXIS := NCAxisName^(*AXIS_REF*),
     OUTAXIS => NCAxisName^(*AXIS_REF*));
NCAxisStop(
     AXIS := NCAxisName^(*AXIS_REF*),
     OUTAXIS => NCAxisName^(*AXIS_REF*));
UpdateStatus(
     AXIS := NCAxisName^(*AXIS_REF*),
     OUTAXIS => NCAxisName^(*AXIS_REF*));
Rtring_Rel(CLK := g_NCMoveData.NCAXISCMD[IndexNumber].NCAxisRel);
IF Rtring_Rel.Q THEN
  g_NCMoveData.NCAXISCMD[IndexNumber].NCAxisRel := FALSE;
  NCAxisRelMoveDone := FALSE;
  dTargetPos1 := NCAxisName^.NCTOPLC.ACTPOS;
  dTargetPos := dTargetPos1 + RelMoceDistance;
  nRelState := 1;
  AxisMoveDone :=FALSE;
  (*IF nRelState <> 0 AND nRelState <> 20 AND NCAxisName.NCTOPLC.ACTVELO > g_dCheckAxisIsMovingSpeedSet THEN
    g_bAxisIsMoveAlarm := TRUE;
      nRelState := 21;
  END_IF;*)

END_IF;
CASE nRelState OF
  0:
    nRelState := 0;
  1:
    NCAxisAbs.Execute := TRUE;
    NCAxisAbs.Velocity := TargetAxisVel;
    NCAxisAbs.Position := dTargetPos;
    IF g_bSetAuxiliaryAxisSpeed THEN
      NCAxisAbs.Velocity := g_nAuxiliaryAxisSpeed;
      g_bSetAuxiliaryAxisSpeed := FALSE;
    END_IF;
    IF NCAxisAbs.Done THEN
      NCAxisAbs.Execute := FALSE;
      NCAxisRelMoveDone := TRUE;
      AxisMoveDone :=TRUE;
      nRelState := 0;
    END_IF;
    IF g_bPlcPauseBuffer THEN      
      NCAxisAbs.Execute := FALSE;
      g_NCMoveData.NCAXISCMD[IndexNumber].NCAxisStop := TRUE;
      nRelState := 20;
    END_IF;
    IF g_bPlcResetBuffer THEN
      nRelState := 21;
    END_IF;
    IF NCAxisAbs.CommandAborted OR NCAxisAbs.Error THEN
      NCAxisAbs.Execute := FALSE;
      nRelState := 0;
    END_IF;
  20:
    NCAxisAbs.Execute := FALSE;
    IF g_NCMoveData.NCAXISDATA[IndexNumber].AxisStopDone  THEN
      g_NCMoveData.NCAXISCMD[IndexNumber].NCAxisStop := FALSE;
    END_IF;

    IF g_NCMoveData.NCAXISDATA[IndexNumber].AxisStopDone AND g_bPlcStartBuffer THEN
      nRelState := 1;
    END_IF;

    IF g_bPlcResetBuffer THEN
      nRelState := 0;
    END_IF;
    IF NCAxisStop.CommandAborted OR NCAxisStop.Error THEN
      NCAxisStop.Execute := FALSE;
      nRelState := 0;
    END_IF;
  21:
    NCAxisAbs.Execute := FALSE;
    g_NCMoveData.NCAXISCMD[IndexNumber].NCAxisStop := TRUE;
    IF g_NCMoveData.NCAXISDATA[IndexNumber].AxisStopDone THEN
      g_NCMoveData.NCAXISCMD[IndexNumber].NCAxisStop := FALSE;
      nRelState := 0;
      NCAxisRelMoveDone := TRUE;
      AxisMoveDone :=TRUE;
    END_IF;
    IF NCAxisStop.CommandAborted OR NCAxisStop.Error THEN
      NCAxisStop.Execute := FALSE;
      nRelState := 0;
    END_IF;
END_CASE;

ERRORID := NCAxisAbs.ERRORID;
